-- Read-only MySQL 8.4 data checks; this file sets only this session's group_concat_max_len, then runs SELECTs.
-- Bucket is the first two hex digits after pl-place-01-; NULL and INVALID are reserved buckets. Relationships bucket by from_place_id. Names and notes are hashed and never returned.
-- Run in one mysql session without --force. The guard returns 1 or raises an SQL error before any digest query runs.
SET SESSION group_concat_max_len = 16777216;
SELECT @@session.group_concat_max_len AS group_concat_limit_bytes,
       @@session.max_allowed_packet AS max_allowed_packet_bytes,
       JSON_VALUE(
         IF(@@session.group_concat_max_len >= 16777216
            AND @@session.max_allowed_packet >= 16777216,
            '{"capacity_ok":1}',
            CONCAT('{invalid:', @@session.group_concat_max_len, '}')),
         '$.capacity_ok' RETURNING UNSIGNED ERROR ON ERROR
       ) AS digest_capacity_check;
SELECT /*+ SET_VAR(time_zone='+00:00') */ bucket,row_count,LOWER(SHA2(CAST(row_hash_list AS BINARY),256)) AS digest_sha256,OCTET_LENGTH(row_hash_list) AS digest_input_bytes,@@session.group_concat_max_len AS group_concat_limit_bytes,@@session.max_allowed_packet AS max_allowed_packet_bytes,@@session.time_zone AS digest_time_zone,(OCTET_LENGTH(row_hash_list)<LEAST(@@session.group_concat_max_len,@@session.max_allowed_packet)) AS digest_complete FROM (SELECT bucket,COUNT(*) AS row_count,GROUP_CONCAT(row_hash ORDER BY CAST(row_hash AS BINARY) SEPARATOR '') AS row_hash_list FROM (SELECT CASE WHEN `place_id` IS NULL THEN 'NULL' WHEN `place_id` REGEXP '^pl-place-01-[0-9A-Fa-f]{24}$' THEN LOWER(SUBSTRING(`place_id`,13,2)) ELSE 'INVALID' END AS bucket,LOWER(SHA2(CAST(CONCAT(IF(`place_id` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`place_id` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`place_id` AS CHAR CHARACTER SET utf8mb4),';')),IF(`place_type` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`place_type` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`place_type` AS CHAR CHARACTER SET utf8mb4),';')),IF(`place_classification` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`place_classification` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`place_classification` AS CHAR CHARACTER SET utf8mb4),';')),IF(`verification_status` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`verification_status` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`verification_status` AS CHAR CHARACTER SET utf8mb4),';')),IF(`lifecycle_status` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`lifecycle_status` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`lifecycle_status` AS CHAR CHARACTER SET utf8mb4),';')),IF(`publication_eligible` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`publication_eligible` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`publication_eligible` AS CHAR CHARACTER SET utf8mb4),';')),IF(`search_eligible` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`search_eligible` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`search_eligible` AS CHAR CHARACTER SET utf8mb4),';')),IF(`search_scope` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`search_scope` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`search_scope` AS CHAR CHARACTER SET utf8mb4),';')),IF(`licensing_classification` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`licensing_classification` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`licensing_classification` AS CHAR CHARACTER SET utf8mb4),';'))) AS BINARY),256)) AS row_hash FROM `place`) AS row_hashes GROUP BY bucket) AS per_bucket ORDER BY bucket;
SELECT /*+ SET_VAR(time_zone='+00:00') */ bucket,row_count,LOWER(SHA2(CAST(row_hash_list AS BINARY),256)) AS digest_sha256,OCTET_LENGTH(row_hash_list) AS digest_input_bytes,@@session.group_concat_max_len AS group_concat_limit_bytes,@@session.max_allowed_packet AS max_allowed_packet_bytes,@@session.time_zone AS digest_time_zone,(OCTET_LENGTH(row_hash_list)<LEAST(@@session.group_concat_max_len,@@session.max_allowed_packet)) AS digest_complete FROM (SELECT bucket,COUNT(*) AS row_count,GROUP_CONCAT(row_hash ORDER BY CAST(row_hash AS BINARY) SEPARATOR '') AS row_hash_list FROM (SELECT CASE WHEN `place_id` IS NULL THEN 'NULL' WHEN `place_id` REGEXP '^pl-place-01-[0-9A-Fa-f]{24}$' THEN LOWER(SUBSTRING(`place_id`,13,2)) ELSE 'INVALID' END AS bucket,LOWER(SHA2(CAST(CONCAT(IF(`place_id` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`place_id` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`place_id` AS CHAR CHARACTER SET utf8mb4),';')),IF(`name` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`name` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`name` AS CHAR CHARACTER SET utf8mb4),';')),IF(`normalized_name` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`normalized_name` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`normalized_name` AS CHAR CHARACTER SET utf8mb4),';')),IF(`name_role` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`name_role` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`name_role` AS CHAR CHARACTER SET utf8mb4),';')),IF(`name_state` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`name_state` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`name_state` AS CHAR CHARACTER SET utf8mb4),';')),IF(`is_searchable` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`is_searchable` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`is_searchable` AS CHAR CHARACTER SET utf8mb4),';')),IF(`evidence_source` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`evidence_source` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`evidence_source` AS CHAR CHARACTER SET utf8mb4),';')),IF(`valid_from` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`valid_from` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`valid_from` AS CHAR CHARACTER SET utf8mb4),';')),IF(`valid_to` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`valid_to` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`valid_to` AS CHAR CHARACTER SET utf8mb4),';'))) AS BINARY),256)) AS row_hash FROM `place_name`) AS row_hashes GROUP BY bucket) AS per_bucket ORDER BY bucket;
SELECT /*+ SET_VAR(time_zone='+00:00') */ bucket,row_count,LOWER(SHA2(CAST(row_hash_list AS BINARY),256)) AS digest_sha256,OCTET_LENGTH(row_hash_list) AS digest_input_bytes,@@session.group_concat_max_len AS group_concat_limit_bytes,@@session.max_allowed_packet AS max_allowed_packet_bytes,@@session.time_zone AS digest_time_zone,(OCTET_LENGTH(row_hash_list)<LEAST(@@session.group_concat_max_len,@@session.max_allowed_packet)) AS digest_complete FROM (SELECT bucket,COUNT(*) AS row_count,GROUP_CONCAT(row_hash ORDER BY CAST(row_hash AS BINARY) SEPARATOR '') AS row_hash_list FROM (SELECT CASE WHEN `from_place_id` IS NULL THEN 'NULL' WHEN `from_place_id` REGEXP '^pl-place-01-[0-9A-Fa-f]{24}$' THEN LOWER(SUBSTRING(`from_place_id`,13,2)) ELSE 'INVALID' END AS bucket,LOWER(SHA2(CAST(CONCAT(IF(`from_place_id` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`from_place_id` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`from_place_id` AS CHAR CHARACTER SET utf8mb4),';')),IF(`to_place_id` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`to_place_id` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`to_place_id` AS CHAR CHARACTER SET utf8mb4),';')),IF(`relationship_type` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`relationship_type` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`relationship_type` AS CHAR CHARACTER SET utf8mb4),';')),IF(`search_scope_authorized` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`search_scope_authorized` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`search_scope_authorized` AS CHAR CHARACTER SET utf8mb4),';')),IF(`evidence_source` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`evidence_source` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`evidence_source` AS CHAR CHARACTER SET utf8mb4),';')),IF(`valid_from` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`valid_from` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`valid_from` AS CHAR CHARACTER SET utf8mb4),';')),IF(`valid_to` IS NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`valid_to` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`valid_to` AS CHAR CHARACTER SET utf8mb4),';'))) AS BINARY),256)) AS row_hash FROM `place_relationship`) AS row_hashes GROUP BY bucket) AS per_bucket ORDER BY bucket;
