S NULL,'N;',CONCAT('V',OCTET_LENGTH(CAST(`note` AS CHAR CHARACTER SET utf8mb4)),':',CAST(`note` AS CHAR CHARACTER SET utf8mb4),';'))) AS BINARY),256)) AS row_hash FROM `place_evidence`) AS row_hashes GROUP BY bucket) AS per_bucket ORDER BY bucket;
